-bottom:1px solid #e1e6ec;padding:13px 0 12px;margin:0 0 30px}.contents b{display:block;font-size:7pt;letter-spacing:1px;color:#65758a;margin-bottom:5px}.contents a{display:inline-block;text-decoration:none;color:#36516c;font-size:7pt;margin:2px 15px 2px 0}section{margin:0 0 28px}h2{font-size:15px;font-weight:600;padding:0 0 10px;border-bottom:1px solid #ccd6e1;margin:30px 0 15px;break-after:avoid}h2 span{display:inline-block;width:34px;color:#8192a4;font-size:10px;vertical-align:middle}h3{font-size:11px;margin:20px 0 9px;break-after:avoid}p{margin:8px 0 12px}table.data{width:100%;border-collapse:collapse;margin:12px 0 16px;font-size:11px;table-layout:auto}table.data thead{display:table-header-group}table.data th{background:#eef2f6;color:#43576d;border-top:1px solid #c7d2df;border-bottom:1px solid #c7d2df;font-size:10px;text-align:left;font-weight:600;padding:9px 8px;white-space:normal}table.data td{padding:8px;border-bottom:1px solid #e3e9ef;vertical-align:top;overflow-wrap:anywhere}table.data tr{break-inside:avoid}table.data tr:nth-child(even) td{background:#fafbfd}.numeric{text-align:right;font-variant-numeric:tabular-nums;font-family:'Segoe UI',Arial,sans-serif;white-space:nowrap}.note{border-left:3px solid #9cabbc;background:#f7f9fb;color:#56697e;font-size:7pt;padding:12px 15px;margin:16px 0}.equation{font:11px 'Cambria Math',Consolas,monospace;line-height:1.6;color:#244868;padding:12px 16px;background:#f3f6fa;border:1px solid #e4eaf1;white-space:pre-wrap;overflow-wrap:anywhere;margin:12px 0;break-inside:avoid}.figure{margin:18px 0;break-inside:avoid;border:1px solid #e0e6ee;padding:12px;background:white}.figure img,.figure svg{display:block;width:100%;height:auto}.figure figcaption{font-size:7pt;line-height:1.5;color:#687a8e;padding:10px 3px 0}.source{font-size:7pt;color:#6c7c8e}.endnote{margin-top:36px;border-top:1px solid #cdd8e3;padding-top:12px;font-size:7pt;color:#69798b}.audit{white-space:pre-wrap;overflow-wrap:anywhere;font:7pt Consolas,monospace;color:#45576b}.page-break{break-before:page}
 @media print{html{scroll-behavior:auto}body{background:white;font-size:8.5pt;line-height:1.25;-webkit-print-color-adjust:exact;print-color-adjust:exact}main{max-width:none;padding:0;margin:0;box-shadow:none}.screen-note,.contents{display:none}.masthead{padding-bottom:8px;border-bottom-width:1px}.brand img{width:34px;height:34px;margin-right:10px}.brand strong{font-size:15pt;line-height:1.1}.brand span,.document-meta{font-size:7pt;letter-spacing:.3px}.title-block{margin:12px 0 10px}.eyebrow,.subtitle{font-size:7pt}h1{font-size:15pt;margin:4px 0 5px}.project{margin-bottom:10px}.project th,.project td{padding:4px 8px;font-size:7.5pt}.project th{font-size:7pt}.highlights{margin-bottom:12px}.highlights td{padding:6px 10px}.highlights span{font-size:7pt}.highlights strong{font-size:12pt;margin-top:3px}section{margin-bottom:12px}h2{font-size:10pt;margin:14px 0 8px;padding-bottom:5px;break-after:avoid}h2 span{font-size:7pt;width:25px}h3{font-size:9pt;margin:10px 0 5px}p{margin:5px 0 7px}table.data{font-size:9pt;line-height:1.28;margin:7px 0 10px}table.data th{font-size:8pt;padding:5px}table.data td{padding:3px 5px}.note{font-size:7pt;line-height:1.3;padding:6px 9px;margin:8px 0;break-inside:avoid}.equation{font-size:8pt;line-height:1.3;padding:7px 10px;margin:8px 0}.figure{padding:7px;margin:9px 0;page-break-inside:avoid}.figure.plan svg{width:156mm;max-width:100%;margin:0 auto}.figure img{max-height:112mm;width:auto;max-width:100%;margin:0 auto}.figure figcaption{font-size:7pt;line-height:1.25;padding-top:5px}.source,.endnote,.audit{font-size:7pt}.endnote{margin-top:14px;padding-top:7px}.page-break{break-before:auto}}

 @media screen and (max-width:760px){main{margin:12px;padding:28px 20px}.screen-note{margin:12px}.screen-note span{float:none;display:block;margin-top:6px}.highlights strong{font-size:17px}.project th{width:80px}}
 ";
}
class EngineeringReportBlock {public string Kind,Text;public string[] Headers;public List<string[]> Rows;}
class EngineeringSection {
 public string Title;public bool NewPage;public readonly List<string> Blocks=new List<string>();public readonly List<EngineeringReportBlock> Records=new List<EngineeringReportBlock>();
 public void Paragraph(string text){Records.Add(new EngineeringReportBlock{Kind="paragraph",Text=text});Blocks.Add("<p>"+EngineeringReport.Escape(text)+"</p>");}
 public void Note(string text){Records.Add(new EngineeringReportBlock{Kind="note",Text=text});Blocks.Add("<div class='note'>"+EngineeringReport.Escape(text)+"</div>");}
 public void Equation(string text){Records.Add(new EngineeringReportBlock{Kind="equation",Text=text});Blocks.Add("<div class='equation'>"+EngineeringReport.Escape(text)+"</div>");}
 public void Table(string[] headers,IEnumerable<string[]> rows){var snapshot=rows.Select(row=>row.ToArray()).ToList();Records.Add(new EngineeringReportBlock{Kind="table",Headers=headers.ToArray(),Rows=snapshot});rows=snapshot;var b=new StringBuilder("<table class='data'><thead><tr>");foreach(var h in headers)b.Append("<th>").Append(EngineeringReport.Escape(h)).Append("</th>");b.Append("</tr></thead><tbody>");foreach(var row in rows){b.Append("<tr>");foreach(var cell in row){double number;bool numeric=double.TryParse(cell,NumberStyles.Float,CultureInfo.InvariantCulture,out number);b.Append(numeric?"<td class=\"numeric\">":"<td>").Append(EngineeringReport.Escape(cell)).Append("</td>");}b.Append("</tr>");}Blocks.Add(b.Append("</tbody></table>").ToString());}
 public void Figure(string imageOrSvg,string caption,bool svg=false){Blocks.Add((svg&&imageOrSvg.Contains("800 610")?"<figure class='figure plan'>":"<figure class='figure'>")+(svg?imageOrSvg:"<img alt='"+EngineeringReport.Escape(caption)+"' src='data:image/png;base64,"+imageOrSvg+"'>")+"<figcaption>"+EngineeringReport.Escape(caption)+"</figcaption></figure>");}
}
static class ProfessionalReport {
 public static EngineeringReport Create(string title,string project,string location,string office=""){var report=new EngineeringReport{Title=title,Project=project,Location=location,Office=office};string logo=
#if ADMIN_APP
 "DtceLogo.png";
#else
 "DpwhLogo.png";
#endif
  using(var input=typeof(ProfessionalReport).Assembly.GetManifestResourceStream(logo))if(input!=null)using(var output=new MemoryStream()){input.CopyTo(output);report.Logo=Convert.ToBase64String(output.ToArray());}return report;}
 static bool FixedTable(EngineeringSection section,string[] lines,ref int index){
  string[] headers=Regex.Split(lines[index].Trim(),@"\s{2,}");if(headers.Length<3||!headers.Any(c=>c.Any(char.IsLetter))||index+1>=lines.Length)return false;
  var rows=new List<string[]>();int next=index+1;while(next<lines.Length){string raw=lines[next].Trim();if(raw.Length==0||raw.StartsWith("##")||Regex.IsMatch(raw,@"^[-=]{3,}$"))break;var cells=Regex.Split(raw,@"\s{2,}");if(cells.Length<2||!cells.Any(c=>Regex.IsMatch(c,@"^[+-]?[0-9.,]+(?:\s*(?:mm|m|kg))?$")))break;var row=new string[headers.Length];for(int c=0;c<row.Length;c++)row[c]=c<cells.Length?cells[c]:"";if(cells.Length>headers.Length)row[row.Length-1]=string.Join(" · ",cells.Skip(headers.Length-1));rows.Add(row);next++;}
  if(rows.Count==0)return false;section.Table(headers,rows);index=next-1;return true;
 }
 public static EngineeringReport FromText(string text,string title,string project,string location,string office=""){
  var report=Create(title,project,location,office);report.Subtitle="Calculation basis, results and numerical workings";var section=report.Section("Calculation record");var lines=text.Replace("\r","").Split('\n');
  for(int index=0;index<lines.Length;index++){string line=lines[index].Trim();if(line==""||line=="\f"||Regex.IsMatch(line,@"^[-=]{3,}$"))continue;if(text.StartsWith("DTCE | DETAILED ")&&index==0)continue;if(text.StartsWith("DTCE | DETAILED ")&&index==1){section.Paragraph(line.Replace(" | "," · "));continue;}if(FixedTable(section,lines,ref index))continue;bool heading=line.StartsWith("## ")||(line.Length>3&&line.Length<85&&line.Any(char.IsLetter)&&line==line.ToUpperInvariant()&&!line.Contains("=")&&!line.Contains("|")&&!line.StartsWith("DTCE"));
   if(heading){section=report.Section(Regex.Replace(line.TrimStart('#',' '),@"^\d{2}\s+", ""));continue;}
   if(line.Contains(" | ")){
    var rows=new List<string[]>();while(index<lines.Length&&lines[index].Contains(" | ")){rows.Add(lines[index].Trim().Split(new[]{" | "},StringSplitOptions.None));index++;}index--;
    int columns=rows.Max(r=>r.Length);string[] headers=Enumerable.Range(0,columns).Select(i=>i==0?"Record":"Value "+i).ToArray();
    if(rows[0].Any(c=>new[]{"Unit","Description","Quantity","Load case","Member","Surface"}.Contains(c,StringComparer.OrdinalIgnoreCase))){headers=rows[0];rows.RemoveAt(0);}
    section.Table(headers,rows.Select(r=>Enumerable.Range(0,columns).Select(i=>i<r.Length?r[i]:"").ToArray()));
   }
   else if(line.Contains("=")&&(line.Any(char.IsDigit)||line.Contains("Σ")))section.Equation(line);else section.Paragraph(line);
  }return report;
 }
}
